mkdir -p /tmp/fanin && cat > /tmp/fanin/main.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type key struct {
	name string
	pos  string
}

func main() {
	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:   "/bench/repo",
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	fset := token.NewFileSet()
	_ = fset
	// counts: target func -> set of call sites (file:line), and set of enclosing caller funcs
	callSites := map[string]map[string]bool{}
	callerFuncs := map[string]map[string]bool{}
	callSitesNonTest := map[string]map[string]bool{}
	label := map[string]string{}

	seenFile := map[string]bool{}

	packages.Visit(pkgs, nil, func(p *packages.Package) {
		if p.TypesInfo == nil {
			return
		}
		if !strings.HasPrefix(p.PkgPath, "github.com/usememos/memos") {
			return
		}
		for _, f := range p.Syntax {
			fpos := p.Fset.Position(f.Pos()).Filename
			if seenFile[fpos] {
				continue
			}
			seenFile[fpos] = true
			// track enclosing function
			var stack []ast.Node
			ast.Inspect(f, func(n ast.Node) bool {
				if n == nil {
					if len(stack) > 0 {
						stack = stack[:len(stack)-1]
					}
					return true
				}
				stack = append(stack, n)
				call, ok := n.(*ast.CallExpr)
				if !ok {
					return true
				}
				var id *ast.Ident
				switch fun := ast.Unparen(call.Fun).(type) {
				case *ast.Ident:
					id = fun
				case *ast.SelectorExpr:
					id = fun.Sel
				default:
					return true
				}
				obj := p.TypesInfo.Uses[id]
				if obj == nil {
					obj = p.TypesInfo.Defs[id]
				}
				fn, ok := obj.(*types.Func)
				if !ok || fn.Pkg() == nil {
					return true
				}
				pp := fn.Pkg().Path()
				if !strings.Contains(pp, "github.com/usememos/memos/internal/") {
					return true
				}
				dpos := fn.Pkg().Path() + "." + fn.FullName()
				sig := fn.FullName()
				declPos := ""
				if fn.Pos().IsValid() {
					declPos = p.Fset.Position(fn.Pos()).String()
				}
				k := dpos
				label[k] = sig + " @ " + declPos
				site := p.Fset.Position(call.Lparen).String()
				if callSites[k] == nil {
					callSites[k] = map[string]bool{}
					callerFuncs[k] = map[string]bool{}
					callSitesNonTest[k] = map[string]bool{}
				}
				callSites[k][site] = true
				if !strings.HasSuffix(strings.Split(site, ":")[0], "_test.go") {
					callSitesNonTest[k][site] = true
				}
				// enclosing func decl
				encl := "?"
				for i := len(stack) - 1; i >= 0; i-- {
					if fd, ok := stack[i].(*ast.FuncDecl); ok {
						encl = p.Fset.Position(fd.Pos()).Filename + ":" + fd.Name.Name
						break
					}
				}
				callerFuncs[k][encl] = true
				return true
			})
		}
	})

	type row struct {
		k                    string
		sites, nonTest, funcs int
	}
	rows := []row{}
	for k, v := range callSites {
		rows = append(rows, row{k, len(v), len(callSitesNonTest[k]), len(callerFuncs[k])})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].sites > rows[j].sites })
	w := os.Stdout
	fmt.Fprintf(w, "%-6s %-8s %-8s %s\n", "SITES", "NONTEST", "CALLERFN", "SYMBOL")
	for i, r := range rows {
		if i > 34 {
			break
		}
		fmt.Fprintf(w, "%-6d %-8d %-8d %s | %s\n", r.sites, r.nonTest, r.funcs, r.k, label[r.k])
	}
}
EOF
